{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Tofacitinib, the closest analogue sharing the N-methyl-pyrrolo[2,3-d]pyrimidine core, has an absolute oral bioavailability of 74% in healthy volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Baricitinib, a sulfonamide-containing JAK inhibitor with the same pyrrolopyrimidine heterocycle, has an absolute oral bioavailability of 80% in healthy volunteers, supporting high F for this sulfonamide-containing analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ruxolitinib, another pyrrolopyrimidine JAK inhibitor, has an absolute oral bioavailability of 74% in humans, reinforcing the high-F pattern for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Sumatriptan, a structurally distant sulfonamide-containing drug, has low oral bioavailability (14%), but its different scaffold and low similarity limit transfer and do not outweigh the JAK inhibitor evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural hybrid of tofacitinib and baricitinib, both JAK inhibitors with high absolute oral bioavailability (74% and ~79-80%) in humans; ruxolitinib also supports high F. The only low-F analogue (sumatriptan) is structurally distant and does not transfer. Therefore predict high (F >= 20%).",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query molecule.",
    "The effect of the cyclobutane propylsulfonamide motif on absorption and first-pass metabolism is inferred from analogues rather than measured directly.",
    "Human absolute bioavailability data are from close analogues, not the query itself."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "JAK inhibitor pyrrolopyrimidine"
    }
  ],
  "revision_action": "initial"
}

